SELECT * FROM review_record
WHERE problem_id = #{problemId}
ORDER BY reviewed_at DESC

SELECT COUNT(DISTINCT problem_id) FROM review_record
WHERE kind = 'MARK_SOLVED'
  AND reviewed_at >= #{start} AND reviewed_at < #{end}

SELECT COUNT(*) FROM review_record
WHERE kind = 'REVIEW'
  AND reviewed_at >= #{start} AND reviewed_at < #{end}
